\label{thm:listdec-cap-large-unbdd}
Let $ N>0 $. 
Then for any $ \varepsilon>0 $, 
\begin{enumerate}
	\item There exist $ (N,L-1) $-multiple packings of rate $ \frac{1}{2}\ln\frac{1}{2\pi eN} - \varepsilon $ for some $ L = {\mathcal O}\mleft(\frac{1}{\varepsilon}\ln\frac{1}{\varepsilon}\mright) $; 

	\item Any $ (N,L-1) $-multiple packing of rate $ \frac{1}{2}\ln\frac{1}{2\pi eN} + \varepsilon $ must satisfy $ L = e^{\Omega(n\varepsilon)} $. 
\end{enumerate}
Therefore, $ C_{\mathrm{LD}}(N) = \frac{1}{2}\ln\frac{1}{2\pi eN} $.

\label{lem:change-var}
Let $ {\mathcal U}\subset{\mathbb R}^n $ be an open set and $ \varphi\colon{\mathcal U}\to{\mathbb R}^n $ be an injective differentiable function with continuous partial derivatives, the Jacobian of which is nonzero for every $ {\underline x}\in{\mathcal U} $.
Then for any compactly supported, continuous function $ f \colon \varphi({\mathcal U})\to{\mathbb R} $, the substitution $ {\underline v} = \varphi({\underline u}) $ yields the following formula
\begin{align}
\int_{\varphi({\mathcal U})} f({\underline v}) \mathrm{d}{\underline v} &= \int_{\mathcal U} f(\varphi({\underline u})) \mleft|\det(\nabla\varphi)({\underline u})\mright| \mathrm{d} {\underline u}, \notag 
\end{align}
where $ \nabla\varphi\in{\mathbb R}^{n\times n} $ denotes the Jacobian matrix of $\varphi$.

\label{thm:lap}
Suppose $ f\colon{\mathbb R}^d\to{\mathbb R} $ is a twice continuously differentiable function on $ {\mathcal A}\subset{\mathbb R}^d $, and there exists a unique point $ \vec t^*\in\operatorname{int}({\mathcal A}) $ (where $ \operatorname{int}(\cdot) $ denotes the interior of a set) such that 
\begin{align}
f(\vec t^*) = \min_{\vec t\in{\mathcal A}} f(\vec t),\quad 
(\operatorname{Hess} f)(\vec t^*) \succ 0, \notag 
\end{align}
where $ \operatorname{Hess} f\in{\mathbb R}^{d\times d} $ denotes the Hessian matrix of $f$. 
Suppose $ g(\vec t) $ is positive. 
Then 
\begin{align}
\int_{{\mathcal A}} g(\vec t)e^{-Mf(\vec t)} \mathrm{d}\vec t 
& \stackrel{M\to\infty}{\asymp} e^{-Mf(\vec t^*)}\mleft(\frac{2\pi}{M}\mright)^{d/2} \frac{g(\vec t^*)}{\sqrt{\det((\operatorname{Hess} f)(\vec t^*))}} . \notag 
\end{align}

\label{thm:cramer-ldp}
Let $ \mleft\{{\mathbf x}_i\mright\}_{i = 1}^n $ be a sequence of i.i.d.\ real-valued random variables. 
Let $ {\mathbf s}_n \coloneq\frac{1}{n}\sum_{i = 1}^n{\mathbf x}_i $. 
Then for any closed $ {\mathcal F}\subset{\mathbb R} $,
\begin{align}
\limsup_{n\to\infty} \frac{1}{n}\ln\Pr\mleft[{\mathbf s}_n\in {\mathcal F}\mright] &\le -\inf_{x\in {\mathcal F}} \sup_{\lambda\in{\mathbb R}}\mleft\{ \lambda x - \ln\mathbb{E}\mleft[e^{\lambda {\mathbf x}_1}\mright] \mright\}; \notag 
\end{align}
and for any open $ {\mathcal G}\subset{\mathbb R} $, 
\begin{align}
\liminf_{n\to\infty} \frac{1}{n}\ln\Pr\mleft[{\mathbf s}_n\in {\mathcal G}\mright] &\ge -\inf_{x\in {\mathcal G}} \sup_{\lambda\in{\mathbb R}}\mleft\{\lambda x - \ln\mathbb{E}\mleft[e^{\lambda {\mathbf x}_1}\mright]\mright\}. \notag 
\end{align}
Furthermore, when ${\mathcal F}$ or ${\mathcal G}$ corresponds to the upper (resp. lower) tail of $ {\mathbf s}_n $, the maximizer $ \lambda\ge0 $ (resp. $ \lambda\le0 $).

\label{def:packing-euclidean}
Let $ N>0 $ and $ L\in{\mathbb Z}_{\ge2} $. 
A subset $ {\mathcal C} \subseteq {\mathbb R}^n $ is called a \emph{$ (N,L-1) $-list-decodable code} (a.k.a.\ an \emph{$(N,L-1)$-multiple packing}) if for every $ {\underline y}\in{\mathbb R}^n $,
\begin{align}
\mleft|{\mathcal C}\cap{\mathcal B}^n({\underline y}, \sqrt{nN})\mright| \le L-1 .
\label{eqn:packing-ball-repeat}
\end{align}
The \emph{rate} (a.k.a.\ \emph{density}) of $ {\mathcal C} $ is defined as 
\begin{align}
R({\mathcal C}) \coloneqq& \limsup_{K\to\infty} \frac{1}{n}\ln\frac{\mleft|{\mathcal C}\cap (K{\mathcal B})\mright|}{\mleft|K{\mathcal B}\mright|}, 
\label{eqn:density-unbounded}
\end{align}
where $ {\mathcal B} $ is an arbitrary centrally symmetric connected compact set in $ {\mathbb R}^n $ with nonempty interior.

\label{def:cheb-rad-avg-rad}
Let $ {\underline x}_1,\cdots,{\underline x}_L $ be $L$ points in $ {\mathbb R}^n $. 
Then the \emph{squared Chebyshev radius} $ \operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) $ of $ {\underline x}_1,\cdots,{\underline x}_L $ is defined as the (squared) radius of the smallest ball containing $ {\underline x}_1,\cdots,{\underline x}_L $, i.e., 
\begin{align}
\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) \coloneqq& \min_{{\underline y}\in{\mathbb R}^n} \max_{i\in[L]} \mleft\|{\underline x}_i - {\underline y}\mright\|_{2}^2. \label{eqn:cheb-rad} 
\end{align}
The \emph{average squared radius} $ \overline\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) $ of $ {\underline x}_1,\cdots,{\underline x}_L $ is defined as the average squared distance to the centroid, i.e., 
\begin{align}
\overline\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) \coloneqq& \frac{1}{L}\sum_{i = 1}^L{\mleft\|{\underline x}_{i} - {\underline x}\mright\|_{2}^2}, \label{eqn:avg-rad}
\end{align}
where $ {\underline x} \coloneqq \frac{1}{L}\sum_{i = 1}^L{\underline x}_i $ is the centroid of $ {\underline x}_1,\cdots,{\underline x}_L $. We refer to the square root of the average squared radius as the average radius of the list.

\label{rk:motivation-avg-rad}
We remark that the motivation behind the definition of average squared radius (\Cref{eqn:avg-rad}) is to replace the maximization in \Cref{eqn:cheb-rad} with average. 
\begin{align}
\min_{{\underline y}\in{\mathbb R}^n} \mathop{\mathbb{E}}_{{\mathbf i}\sim[L]}\mleft[\mleft\|{\underline x}_{\mathbf i} - {\underline y}\mright\|_{2}^2\mright] 
&= \min_{{\underline y}\in{\mathbb R}^n} \frac{1}{L}\sum_{i = 1}^L \sum_{j = 1}^n \mleft({\underline x}_i(j) - {\underline y}(j)\mright)^2 \notag\\
&= \min_{(y_1,\cdots,y_n)\in{\mathbb R}^n} \sum_{j = 1}^n \frac{1}{L}\sum_{i = 1}^L\mleft({\underline x}_i(j) - y_j\mright)^2 \label{eqn:before-interchange} \\
&= \sum_{j = 1}^n \min_{y_j\in{\mathbb R}} \frac{1}{L}\sum_{i = 1}^L\mleft({\underline x}_i(j) - y_j\mright)^2 \label{eqn:interchange} \\
&= \frac{1}{L}\sum_{i = 1}^L\sum_{j = 1}^n\mleft({\underline x}_i(j) - y_j^*\mright)^2 \label{eqn:opt-y} \\
&= \frac{1}{L} \sum_{i = 1}^L \mleft\|{\underline x}_i - {\underline x}\mright\|_{2}^2. \label{eqn:relax-formula}
\end{align}
\Cref{eqn:interchange} holds since the inner summation $ \frac{1}{L}\sum_{i = 1}^L \mleft({\underline x}_i(j) - {\underline y}(j)\mright)^2 $ in \Cref{eqn:before-interchange} only depends on $ y_j $ among all $ y_1,\cdots,y_n $. 
\Cref{eqn:opt-y} follows since for each $j$, the minimizer of the minimization in \Cref{eqn:interchange} is $ y_j^* \coloneqq \frac{1}{L}\sum_{i = 1}^L{\underline x}_i(j) $. 
In \Cref{eqn:relax-formula}, the minimizer $ {\underline y}^* $ equals $ {\underline x} \coloneqq \frac{1}{L}\sum_{i = 1}^L{\underline x}_i $.

\label{def:cheb-rad-avg-rad-code}
Given a code $ {\mathcal C}\subset{\mathbb R}^n $ of rate $R$, the squared \emph{$(L-1)$-list-decoding radius} of ${\mathcal C}$ is defined as
\begin{align}
\operatorname{rad}^2_L({\mathcal C}) \coloneqq&  \min_{{\mathcal L}\in\binom{{\mathcal C}}{L}} \operatorname{rad}^2({\mathcal L}). \label{eqn:rad-code}
\end{align}
The \emph{$(L-1)$-average squared radius} of ${\mathcal C}$ is defined as 
\begin{align}
\overline\operatorname{rad}^2_L({\mathcal C}) \coloneqq& \min_{{\mathcal L}\in\binom{{\mathcal C}}{L}} \overline\operatorname{rad}^2({\mathcal L}). \label{eqn:avgrad-code}
\end{align}

\label{def:avg-rad-multi-pack-unbounded}
A subset $ {\mathcal C}\subset{\mathbb R}^n $ is called an \emph{$ (N,L-1) $-average-radius list-decodable code} (a.k.a.\ an \emph{$ (N,L-1) $-average-radius multiple packing}) if $ \overline\operatorname{rad}^2_L({\mathcal C})>nN $. 
The \emph{rate} (a.k.a.\ \emph{density}) $ R({\mathcal C}) $ of $ {\mathcal C} $ is given by \Cref{eqn:density-unbounded}. 
The \emph{$(N,L-1)$-average-radius list-decoding capacity} (a.k.a.\ \emph{$(N,L-1)$ average-radius multiple packing density}) is defined as
$$ \overline C_{L-1}(N) \coloneqq \limsup_{n\to\infty} \limsup_{{\mathcal C} \subseteq {\mathbb R}^n\colon \overline\operatorname{rad}^2_L({\mathcal C})>nN} R({\mathcal C}) .$$ 
The \emph{squared $(L-1)$-average-radius list-decoding radius} at rate $R$ (without input constraint) is defined as
\begin{align} 
\overline\operatorname{rad}^2_L(R) \coloneqq& \limsup_{n\to\infty} \limsup_{{\mathcal C} \subseteq {\mathbb R}^n \colon R({\mathcal C})\ge R} \overline\operatorname{rad}^2_L({\mathcal C}). \notag 
\end{align}

\label{thm:repr-rad}
Let $ L\in{\mathbb Z}_{\ge2} $ and $ {\underline x}_1,\cdots,{\underline x}_L\in{\mathbb R}^n $. 
Then the squared Chebyshev radius of $ {\underline x}_1,\cdots,{\underline x}_L $ admits the following alternative representations: 
\begin{enumerate}
\item 
$\begin{aligned}
\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) &= \max_{{\vec z}\in\Delta_L} \sum_{i = 1}^L{\vec z}(i)\mleft\|{\underline x}_i - {\underline y}_{\vec z}\mright\|_{2}^2, \notag 
\end{aligned}$
where $ {\underline y}_{\vec z} \coloneqq \sum_{i = 1}^L{\vec z}(i){\underline x}_i $ and $ \Delta_L $ denotes the probability simplex on $ [L] $;

\item 
$\begin{aligned}
\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) &= \lim_{p\to\infty} \operatorname{rad}^{(p)}({\underline x}_1,\cdots,{\underline x}_L), \notag 
\end{aligned}$
where 
\begin{align}
\operatorname{rad}^{(p)}({\underline x}_1,\cdots,{\underline x}_L) &\coloneqq \mleft(\min_{{\underline y}\in{\mathbb R}^n}\frac{1}{L}\sum_{i = 1}^L\mleft\|{\underline x}_i - {\underline y}\mright\|_{2}^{2p}\mright)^{1/p}; \notag 
\end{align} 

\item 
there exists a unique $ 1\le q\le\infty $ depending on $ {\underline x}_1,\cdots,{\underline x}_L $ such that 
\begin{align}
\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) &= \mleft(\frac{1}{L}\sum_{i = 1}^L\mleft\|{\underline x}_i - {\underline x}\mright\|_{2}^{2q}\mright)^{1/q}, \notag 
\end{align}
and $ {\underline x}\coloneqq\frac{1}{L}\sum_{i = 1}^L{\underline x}_i $. 
\end{enumerate}

The average squared radius of $ {\underline x}_1,\cdots,{\underline x}_L $ admits the following alternative representations:
\begin{enumerate}
\item 
$\begin{aligned}
\overline\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) &= \frac{1}{L}\sum_{i = 1}^L\mleft\|{\underline x}_i\mright\|_{2}^2 - \mleft\|{\underline x}\mright\|_{2}^2; \notag 
\end{aligned}$

\item 
$\begin{aligned}
\overline\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L) 
&= \frac{L-1}{L^2}\sum_{i = 1}^L\mleft\|{\underline x}_i\mright\|_{2}^2 - \frac{1}{L^2}\sum_{(i,j)\in[L]^2:i\ne j} \mleft\langle{\underline x}_i,{\underline x}_j\mright\rangle; \notag 
\end{aligned}$

\item 
$\begin{aligned}
\overline\operatorname{rad}^2({\underline x}_1,\cdots,{\underline x}_L)
&= \frac{1}{2L^2}\sum_{(i,j)\in[L]^2:i\ne j} \mleft\|{\underline x}_i - {\underline x}_j\mright\|_{2}^2. \notag 
\end{aligned}$
\end{enumerate}

\label{thm:lb-ppp}
For any $ N>0 $ and $ L\in{\mathbb Z}_{\ge2} $, the $ (N,L-1) $-average-radius list-decoding capacity is at least 
\begin{align}
\overline C_{L-1}(N) &\ge \frac{1}{2}\ln\frac{L-1}{2\pi eNL} - \frac{1}{2(L-1)}\ln L. \label{eqn:lb-ppp} 
\end{align}
